"""test_consumable_spec.py — data-driven behavioral validation of the Tarot /
Planet / Spectral layer against tools/consumable_spec.json (the reference-doc
§3-§5 contract, generated by tools/gen_consumable_spec.py).

The static audit (tools/audit_consumables_static.py) guarantees STRUCTURE:
names, counts, planet hand-type mapping, target maxes, and that each card's
apply_* branch contains the doc's effect semantics. This file guarantees
BEHAVIOR: applying each card to a scratch game produces the doc's documented
outcome. When a row's expectation disagrees with the sim, the sim is wrong —
fix the sim, not the test.
"""
from __future__ import annotations

import json
import pathlib

import pytest

from balatro_sim.card import Card
from balatro_sim.consumables import (
    PLANET_HAND,
    TAROT_ENHANCEMENT,
    TAROT_SUIT,
    VOUCHER_BASE,
    VOUCHER_NAME,
    apply_planet,
    apply_spectral,
    apply_tarot,
    apply_voucher,
)
from balatro_sim.game import HAND_SIZE, BalatroGame

ROOT = pathlib.Path(__file__).resolve().parents[3]
SPEC = json.load(open(ROOT / "tools" / "consumable_spec.json", encoding="utf-8"))

ALL_HANDS = [
    "High Card", "Pair", "Two Pair", "Three of a Kind", "Straight", "Flush",
    "Full House", "Four of a Kind", "Straight Flush", "Five of a Kind",
    "Flush House", "Flush Five",
]


def _game(hand=None) -> BalatroGame:
    g = BalatroGame(seed=0, rng_mode="generic")
    if hand is not None:
        g.hand = hand
    return g


# ── routing smoke: EVERY card must apply successfully (the "wired" gate) ────

@pytest.mark.parametrize("key", sorted(SPEC["planets"]), ids=lambda k: k)
def test_planet_applies(key):
    assert apply_planet(_game(), key)


@pytest.mark.parametrize("key", sorted(SPEC["tarots"]), ids=lambda k: k)
def test_tarot_applies(key):
    assert apply_tarot(_game(hand=[Card(5, "Hearts"), Card(6, "Spades")]), key)


@pytest.mark.parametrize("key", sorted(SPEC["spectrals"]), ids=lambda k: k)
def test_spectral_applies(key):
    assert apply_spectral(_game(hand=[Card(5, "Hearts"), Card(6, "Spades")]), key)


# ── planets: level up exactly the doc's hand type ───────────────────────────

@pytest.mark.parametrize(
    "key,entry", sorted(SPEC["planets"].items()),
    ids=[k for k, _ in sorted(SPEC["planets"].items())])
def test_planet_levels_up_doc_hand(key, entry):
    g = _game()
    before = {h: g.planet_levels[h] for h in ALL_HANDS}
    assert apply_planet(g, key)
    assert PLANET_HAND[key] == entry["hand_type"]
    assert g.planet_levels[entry["hand_type"]] == before[entry["hand_type"]] + 1
    for h in ALL_HANDS:
        if h != entry["hand_type"]:
            assert g.planet_levels[h] == before[h]


# ── enhancement tarots: doc enhancement, doc target max ─────────────────────

_ENH_TAROTS = [(k, e) for k, e in sorted(SPEC["tarots"].items())
                if k in TAROT_ENHANCEMENT]
_SUIT_TAROTS = [(k, e) for k, e in sorted(SPEC["tarots"].items())
                 if k in TAROT_SUIT]


@pytest.mark.parametrize("key,entry", _ENH_TAROTS,
                         ids=[k for k, _ in _ENH_TAROTS])
def test_enhancement_tarot_applies_doc_enhancement(key, entry):
    g = _game(hand=[Card(5, "Hearts"), Card(6, "Spades")])
    assert apply_tarot(g, key, target_indices=[0, 1])
    # The doc says "Enhances ... into <enhancement>"; the audit pins
    # TAROT_ENHANCEMENT's values against the doc, so this asserts the sim's
    # map actually got applied to the cards.
    assert g.hand[0].enhancement == TAROT_ENHANCEMENT[key]
    # at most `targets` cards may be modified (1-card tarots must ignore idx 1)
    changed = sum(1 for c in g.hand if c.enhancement == TAROT_ENHANCEMENT[key])
    assert changed <= entry["targets"]


# ── suit tarots: doc suit, up to 3 cards ────────────────────────────────────

# 4th card suit must differ from the target suit so "untouched" is visible.
_ALL_SUITS = ["Spades", "Hearts", "Clubs", "Diamonds"]
_OTHER_SUIT = {k: next(s for s in _ALL_SUITS if s != TAROT_SUIT[k])
               for k in TAROT_SUIT}


@pytest.mark.parametrize("key,entry", _SUIT_TAROTS,
                         ids=[k for k, _ in _SUIT_TAROTS])
def test_suit_tarot_converts_to_doc_suit(key, entry):
    g = _game(hand=[Card(5, "Hearts"), Card(6, "Spades"),
                    Card(7, "Clubs"), Card(9, _OTHER_SUIT[key])])
    assert apply_tarot(g, key, target_indices=[0, 1, 2, 3])
    want = TAROT_SUIT[key]
    assert g.hand[0].suit == want and g.hand[1].suit == want
    assert g.hand[2].suit == want
    assert g.hand[3].suit != want  # 4th untouched (doc: 1-3 targets)


# ── special tarots ──────────────────────────────────────────────────────────

def test_hermit_doubles_money_capped_at_20_gain():
    for dollars, expected in ((15, 30), (20, 40), (35, 55)):
        g = _game()
        g.dollars = dollars
        assert apply_tarot(g, "c_hermit")
        assert g.dollars == expected  # gain = min(dollars, 20)


def test_temperance_pays_sell_value_capped_at_50():
    g = _game()
    g.jokers = []
    g.dollars = 0
    assert apply_tarot(g, "c_temperance")
    assert g.dollars == 0  # nothing owned -> nothing gained

    g2 = _game()
    g2.dollars = 0
    j = g2.grant_joker("j_half")
    j.state["sell_value"] = 6
    j2 = g2.grant_joker("j_mystic_summit")
    j2.state["sell_value"] = 4
    assert apply_tarot(g2, "c_temperance")
    assert g2.dollars == 10  # 6 + 4


class _FakeRng:
    """Deterministic RNG stub: wheel roll always hits (random() < 0.25) and
    the first choice wins — no dependence on generic-mode seeding."""
    class _Node:
        def random(self):
            return 0.1
        def choice(self, seq):
            return seq[0]
    def node(self, *_a):
        return self._Node()


def test_wheel_of_fortune_gives_edition_on_hit():
    g = _game()
    j = g.grant_joker("j_half")
    g.rng = _FakeRng()
    assert apply_tarot(g, "c_wheel_of_fortune")
    assert j.edition == "Foil"


def test_strength_increments_rank_and_wraps_ace():
    g = _game(hand=[Card(13, "Hearts"), Card(14, "Spades")])
    assert apply_tarot(g, "c_strength", target_indices=[0, 1])
    assert g.hand[0].rank == 14  # King -> Ace
    assert g.hand[1].rank == 2   # Ace wraps to 2


def test_high_priestess_and_emperor_create_with_room():
    g = _game()
    assert apply_tarot(g, "c_high_priestess")
    assert len(g.consumable_hand) == 2
    g2 = _game()
    assert apply_tarot(g2, "c_emperor")
    assert len(g2.consumable_hand) == 2


def test_judgement_grants_joker():
    g = _game()
    assert apply_tarot(g, "c_judgement")
    assert len(g.jokers) == 1


# ── spectrals ───────────────────────────────────────────────────────────────

@pytest.mark.parametrize("key,seal",
                         [("s_talisman", "Gold"), ("s_deja_vu", "Red"),
                          ("s_trance", "Blue"), ("s_medium", "Purple")])
def test_seal_spectral_applies_to_one_card(key, seal):
    g = _game(hand=[Card(5, "Hearts"), Card(6, "Spades")])
    assert apply_spectral(g, key, target_indices=[0, 1])
    assert g.hand[0].seal == seal
    assert g.hand[1].seal == "None"


def test_aura_adds_edition_to_playing_card():
    # Doc §5: Aura targets a PLAYING CARD in hand, not a joker (the sim
    # previously applied the edition to a joker — fixed 2026-08-07).
    g = _game(hand=[Card(5, "Hearts"), Card(6, "Spades")])
    j = g.grant_joker("j_half")
    assert apply_spectral(g, "s_aura", target_indices=[0])
    assert g.hand[0].edition in ("Foil", "Holographic", "Polychrome")
    assert g.hand[1].edition == "None"
    assert j.edition == "None"  # NOT the joker


def test_wraith_creates_rare_joker_and_zeroes_money():
    g = _game()
    g.dollars = 10
    assert apply_spectral(g, "s_wraith")
    assert len(g.jokers) == 1
    assert g.dollars == 0


def test_immolate_destroys_5_cards_and_gains_20():
    g = _game(hand=[Card(r, "Hearts") for r in range(2, 8)])  # 6 cards
    g.dollars = 0
    assert apply_spectral(g, "s_immolate")
    assert len(g.hand) == 1  # 6 - 5
    assert g.dollars == 20


def test_cryptid_creates_two_copies():
    g = _game(hand=[Card(5, "Hearts")])
    g.hand[0].seal = "Gold"
    assert apply_spectral(g, "s_cryptid", target_indices=[0])
    copies = g.hand[1:]
    assert len(copies) == 2  # created INTO HAND (doc §5)
    for c in copies:
        assert c.rank == 5 and c.suit == "Hearts" and c.seal == "Gold"


def test_familiar_grim_incantation_counts():
    # Familiar: -1 card, +3 enhanced faces | Grim: -1, +2 aces
    # Incantation: -1, +4 enhanced numbers — all created INTO HAND (doc §5;
    # the sim previously inserted into the deck).
    for key, add, rankfn in (
            ("s_familiar", 3, lambda c: c.rank in (11, 12, 13)),
            ("s_grim", 2, lambda c: c.rank == 14),
            ("s_incantation", 4, lambda c: 2 <= c.rank <= 10)):
        g = _game(hand=[Card(5, "Hearts"), Card(6, "Spades")])
        assert apply_spectral(g, key, target_indices=[0])
        created = g.hand[1:]                 # one destroyed, N added to hand
        assert len(created) == add
        assert all(rankfn(c) for c in created)
        assert all(c.enhancement != "None" for c in created)


def test_soul_grants_legendary_joker():
    g = _game()
    assert apply_spectral(g, "s_soul")
    assert len(g.jokers) == 1


def test_black_hole_upgrades_every_hand():
    g = _game()
    assert apply_spectral(g, "s_black_hole")
    assert all(v == 2 for v in g.planet_levels.values())


# ── spectrals: corrected semantics (doc §5 + balatro-rs cross-check) ────────

def test_ectoplasm_negatives_one_joker_and_shrinks_hand_permanently():
    g = _game()
    for _ in range(3):
        g.grant_joker("j_half")
    prev_slots = g.joker_slots
    assert apply_spectral(g, "s_ectoplasm")
    assert sum(1 for j in g.jokers if j.edition == "Negative") == 1
    assert g.joker_slots == prev_slots + 1  # negatived joker freed its slot
    assert g.hand_size_mod == -1            # PERMANENT (doc §5)


def test_ectoplasm_noop_without_jokers():
    g = _game()
    prev_slots = g.joker_slots
    assert apply_spectral(g, "s_ectoplasm")
    assert g.joker_slots == prev_slots
    assert g.hand_size_mod == 0


def test_ankh_keeps_original_and_copy():
    # Doc §5: destroys all OTHER jokers — the chosen original survives
    # alongside its copy (balatro-rs: `vec![original, clone]`).
    g = _game()
    g.grant_joker("j_half")
    assert apply_spectral(g, "s_ankh")
    assert len(g.jokers) == 2
    assert g.jokers[0].key == g.jokers[1].key == "j_half"


def test_ankh_copy_strips_negative_edition():
    g = _game()
    j = g.grant_joker("j_half")
    j.edition = "Negative"
    assert apply_spectral(g, "s_ankh")
    assert len(g.jokers) == 2
    assert {jj.edition for jj in g.jokers} == {"Negative", "None"}


def test_ouija_hand_size_reduction_is_permanent():
    g = _game(hand=[Card(2, "Hearts"), Card(3, "Spades")])
    assert apply_spectral(g, "s_ouija")
    assert g.hand_size_mod == -1
    assert g.hand_size == HAND_SIZE - 1


def test_hand_size_mod_applies_each_blind():
    # The permanent -1 (Ouija/Ectoplasm) survives the per-blind hand_size
    # reset because _start_blind derives from HAND_SIZE + hand_size_mod.
    g = _game()
    g.hand_size_mod = -2
    g._start_blind()
    assert g.hand_size == HAND_SIZE - 2


