@pytest.mark.parametrize("key", sorted(SPEC["vouchers"]), ids=lambda k: k)
def test_voucher_applies(key):
    assert apply_voucher(_game(), key)  # routing smoke (the WIRED gate)


@pytest.mark.parametrize("key,entry",
                         sorted(SPEC["vouchers"].items()),
                         ids=[k for k, _ in sorted(SPEC["vouchers"].items())])
def test_voucher_name_matches_doc(key, entry):
    assert VOUCHER_NAME[key] == entry["name"]


_UPGRADES = [(k, e) for k, e in sorted(SPEC["vouchers"].items())
             if not e["base"]]


@pytest.mark.parametrize("key,entry", _UPGRADES,
                         ids=[k for k, _ in _UPGRADES])
def test_upgrade_pairs_match_doc(key, entry):
    # Doc §9 pairs each upgrade with its base; VOUCHER_BASE must encode the
    # exact same 16 pairs (a missing pair = the upgrade offered pre-base).
    assert VOUCHER_BASE[key] == entry["upgrade_of"]


#: (key, attribute, delta) — vouchers whose apply_voucher effect is a simple
#: state bump (asserted on a fresh game).
_VOUCHER_STATE = [
    ("v_overstock", "shop_item_slots", 1),
    ("v_crystal_ball", "consumable_slots", 1),
    ("v_grabber", "base_hands", 1),
    ("v_wasteful", "base_discards", 1),
    ("v_reroll_surplus", "reroll_discount", 2),
    ("v_antimatter", "joker_slots", 1),
    ("v_paint_brush", "hand_size", 1),
    ("v_clearance_sale", "shop_discount", 0.25),
]


@pytest.mark.parametrize("key,attr,delta", _VOUCHER_STATE,
                         ids=[k for k, _, _ in _VOUCHER_STATE])
def test_voucher_state_effect(key, attr, delta):
    g = _game()
    before = getattr(g, attr)
    assert apply_voucher(g, key)
    assert getattr(g, attr) == before + delta


def test_seed_money_and_money_tree_interest_caps():
    # Doc §9: Seed Money "raises interest cap by $5", Money Tree "by $10 more".
    g = _game()
    assert g.interest_cap == 5
    apply_voucher(g, "v_seed_money")
    assert g.interest_cap == 10
    apply_voucher(g, "v_money_tree")
    assert g.interest_cap == 20


def test_hieroglyph_and_petroglyph_reduce_ante():
    g = _game()
    g.ante = 3
    hands_before = g.base_hands
    apply_voucher(g, "v_hieroglyph")
    assert g.ante == 2                 # -1 ante
    assert g.base_hands == hands_before - 1  # -1 hand per round
    g2 = _game()
    g2.ante = 3
    disc_before = g2.base_discards
    apply_voucher(g2, "v_petroglyph")
    assert g2.ante == 2                # -1 ante
    assert g2.base_discards == disc_before - 1  # -1 discard per round


def test_blank_changes_nothing():
    g = _game()
    state = (g.shop_item_slots, g.shop_discount, g.consumable_slots,
             g.joker_slots, g.base_hands, g.base_discards, g.interest_cap,
             g.hand_size)
    assert apply_voucher(g, "v_blank")
    assert "v_blank" in g.vouchers
    assert (g.shop_item_slots, g.shop_discount, g.consumable_slots,
            g.joker_slots, g.base_hands, g.base_discards, g.interest_cap,
            g.hand_size) == state


_ENGINE_VOUCHERS = ["v_hone", "v_glow_up", "v_omen_globe", "v_telescope",
                    "v_observatory", "v_tarot_merchant", "v_tarot_tycoon",
                    "v_planet_merchant", "v_planet_tycoon", "v_magic_trick",
                    "v_illusion", "v_directors_cut", "v_retcon"]


@pytest.mark.parametrize("key", _ENGINE_VOUCHERS)
def test_engine_voucher_owned_on_apply(key):
    # Engine-implemented vouchers (shop.py/scoring.py/game.py) — the audit
    # verifies each is referenced by its engine file; here we smoke the apply.
    g = _game()
    assert apply_voucher(g, key)
    assert key in g.vouchers


def test_sigil_exempts_stone_cards():
    # Real-game behavior: Stone cards are unaffected by suit conversions.
    g = _game(hand=[Card(2, "Hearts"), Card(3, "Spades"), Card(4, "Clubs")])
    g.hand[0].enhancement = "Stone"
    assert apply_spectral(g, "s_sigil")
    assert g.hand[0].suit == "Hearts"          # Stone keeps its suit
    assert g.hand[1].suit == g.hand[2].suit     # others all one suit


def test_ouija_exempts_stone_cards():
    g = _game(hand=[Card(2, "Hearts"), Card(3, "Spades"), Card(4, "Clubs")])
    g.hand[0].enhancement = "Stone"
    assert apply_spectral(g, "s_ouija")
    assert g.hand[0].rank == 2                  # Stone keeps its rank
    assert g.hand[1].rank == g.hand[2].rank     # others all one rank
